using System.Text.Json;
using Npgsql;
using ShelfSync.Api.Models;
using ShelfSync.Api.Services;
using ShelfSync.Api.Repositories;
namespace ShelfSync.Tests;
public sealed class StoreOperationsTests
{
 static StoreOperationsService Store(PostgresTestScope f)=>new(new(f.Db));
 static CartReservationService Cart(PostgresTestScope f)=>new(new(f.Db));
 static async Task<long> Scalar(PostgresTestScope f,string sql){await using var c=f.Db.CreateCommand(sql);c.Parameters.AddWithValue(f.ProductId);return Convert.ToInt64(await c.ExecuteScalarAsync());}
 static async Task<Guid> Reserve(PostgresTestScope f,int quantity){var r=await new ReservationService(f.Db).CreateAsync(new(f.ProductId,quantity),f.NewRequestKey());Assert.Equal(201,r.StatusCode);return JsonDocument.Parse(r.Json).RootElement.GetProperty("orderId").GetGuid();}
 [Fact] public async Task Receive_IsReplaySafe_AndDoesNotExposeBackroomAsShelf()
 {await using var f=await PostgresTestScope.CreateAsync();var s=Store(f);var key=f.NewRequestKey();var request=new StockMovementRequest(f.ProductId,12,"Delivery checked","PO-123");Assert.Equal(200,(await s.MoveAsync("RECEIVE_BACKROOM",request,key,"associate")).StatusCode);Assert.Equal(200,(await s.MoveAsync("RECEIVE_BACKROOM",request,key,"associate")).StatusCode);var details=await new ProductDetailsRepository(f.Db).GetAsync(f.ProductId);Assert.Contains(details!.Activity,e=>e.Actor=="associate"&&e.Reason=="Delivery checked");Assert.Equal(12,await Scalar(f,"SELECT backroom_units FROM inventory WHERE product_id=$1"));Assert.Equal(10,await Scalar(f,"SELECT shelf_units FROM inventory WHERE product_id=$1"));Assert.Equal(409,(await s.MoveAsync("RECEIVE_BACKROOM",request with{Quantity=13},key,"associate")).StatusCode);}
 [Fact] public async Task Replenishment_TransfersUnits_AndRejectsOverdraw()
 {await using var f=await PostgresTestScope.CreateAsync();var s=Store(f);await s.MoveAsync("RECEIVE_BACKROOM",new(f.ProductId,6,"Delivery checked",null),f.NewRequestKey(),"associate");Assert.Equal(200,(await s.MoveAsync("REPLENISH_SHELF",new(f.ProductId,4,"Shelf needs stock",null),f.NewRequestKey(),"associate")).StatusCode);Assert.Equal(2,await Scalar(f,"SELECT backroom_units FROM inventory WHERE product_id=$1"));Assert.Equal(14,await Scalar(f,"SELECT shelf_units FROM inventory WHERE product_id=$1"));Assert.Equal(409,(await s.MoveAsync("REPLENISH_SHELF",new(f.ProductId,3,"Too many units",null),f.NewRequestKey(),"associate")).StatusCode);}
 [Fact] public async Task InvalidMovement_DoesNotChangeStock()
 {await using var f=await PostgresTestScope.CreateAsync();Assert.Equal(400,(await Store(f).MoveAsync("RECEIVE_BACKROOM",new(f.ProductId,-1,"Bad quantity",null),f.NewRequestKey(),"associate")).StatusCode);Assert.Equal(0,await Scalar(f,"SELECT backroom_units FROM inventory WHERE product_id=$1"));}
 [Fact] public async Task PickedCancellation_MovesStockOnce_AndCannotFulfillAfterwards()
 {await using var f=await PostgresTestScope.CreateAsync();var id=await Reserve(f,3);Assert.Equal(200,(await new OrderPickingService(f.Db).PickAsync(id,f.NewRequestKey())).StatusCode);var key=f.NewRequestKey();var req=new PickedCancellationRequest("backroom","Customer cancelled pickup");Assert.Equal(200,(await Store(f).CancelPickedAsync(id,req,key,"manager")).StatusCode);Assert.Equal(200,(await Store(f).CancelPickedAsync(id,req,key,"manager")).StatusCode);Assert.Equal(3,await Scalar(f,"SELECT backroom_units FROM inventory WHERE product_id=$1"));Assert.Equal(0,await Scalar(f,"SELECT picked_units FROM inventory WHERE product_id=$1"));Assert.Equal(409,(await new OrderFulfillmentService(f.Db).FulfillAsync(id,f.NewRequestKey())).StatusCode);}
 [Fact] public async Task PickedCancellation_CompetingWithFulfillment_HasOneWinner()
 {await using var f=await PostgresTestScope.CreateAsync();var id=await Reserve(f,2);await new OrderPickingService(f.Db).PickAsync(id,f.NewRequestKey());var results=await Task.WhenAll(Store(f).CancelPickedAsync(id,new("damaged","Items were damaged"),f.NewRequestKey(),"manager"),new OrderFulfillmentService(f.Db).FulfillAsync(id,f.NewRequestKey()));Assert.Single(results,r=>r.StatusCode==200);Assert.Single(results,r=>r.StatusCode==409);Assert.Equal(0,await Scalar(f,"SELECT picked_units FROM inventory WHERE product_id=$1"));}
 [Fact] public async Task FulfilledReturns_CannotExceedSoldQuantity_AcrossDispositions()
 {await using var f=await PostgresTestScope.CreateAsync();var id=await Reserve(f,3);await new OrderPickingService(f.Db).PickAsync(id,f.NewRequestKey());await new OrderFulfillmentService(f.Db).FulfillAsync(id,f.NewRequestKey());var s=Store(f);Assert.Equal(200,(await s.ReturnAsync(new(id,false,2,"backroom","Unopened return"),f.NewRequestKey(),"manager")).StatusCode);Assert.Equal(200,(await s.ReturnAsync(new(id,false,1,"damaged","Damaged return"),f.NewRequestKey(),"manager")).StatusCode);Assert.Equal(409,(await s.ReturnAsync(new(id,false,1,"backroom","Excess return"),f.NewRequestKey(),"manager")).StatusCode);Assert.Equal(2,await Scalar(f,"SELECT backroom_units FROM inventory WHERE product_id=$1"));Assert.Equal(1,await Scalar(f,"SELECT damaged_units FROM inventory WHERE product_id=$1"));}
 [Fact] public async Task PosReturn_ConcurrentRequests_CannotDuplicateStock()
 {await using var f=await PostgresTestScope.CreateAsync();var sale=Guid.NewGuid();Assert.Equal(200,(await new PosSaleService(f.Db).RecordAsync(new(sale,f.ProductId,2))).StatusCode);var req=new ReturnRequest(sale,true,2,"backroom","Checked return");var results=await Task.WhenAll(Store(f).ReturnAsync(req,f.NewRequestKey(),"manager"),Store(f).ReturnAsync(req,f.NewRequestKey(),"manager"));Assert.Single(results,r=>r.StatusCode==200);Assert.Single(results,r=>r.StatusCode==409);Assert.Equal(2,await Scalar(f,"SELECT backroom_units FROM inventory WHERE product_id=$1"));}
 [Fact] public async Task UnfulfilledOrder_CannotBeReturned()
 {await using var f=await PostgresTestScope.CreateAsync();var id=await Reserve(f,1);Assert.Equal(409,(await Store(f).ReturnAsync(new(id,false,1,"backroom","Must be rejected"),f.NewRequestKey(),"manager")).StatusCode);}
 [Fact] public async Task Cart_IsAtomic_WhenAnyLineIsUnavailable()
 {await using var a=await PostgresTestScope.CreateAsync();await using var b=await PostgresTestScope.CreateAsync(0);var owner=await a.NewAccountAsync();var result=await Cart(a).ReserveAsync(new([new(a.ProductId,1),new(b.ProductId,1)]),a.NewRequestKey(),owner);Assert.Equal(409,result.StatusCode);Assert.Equal(0,await Scalar(a,"SELECT count(*) FROM orders WHERE product_id=$1"));Assert.Equal(0,await Scalar(b,"SELECT count(*) FROM orders WHERE product_id=$1"));}
 [Fact] public async Task Cart_Replay_IsCanonical_AndPreservesOwnerAndPrice()
 {await using var a=await PostgresTestScope.CreateAsync();await using var b=await PostgresTestScope.CreateAsync();var owner=await a.NewAccountAsync();var key=a.NewRequestKey();var service=Cart(a);var result=await service.ReserveAsync(new([new(a.ProductId,2),new(b.ProductId,1)]),key,owner);Assert.Equal(201,result.StatusCode);var replay=await service.ReserveAsync(new([new(b.ProductId,1),new(a.ProductId,2)]),key,owner);Assert.Equal(JsonDocument.Parse(result.Json).RootElement.GetProperty("cartId").GetGuid(),JsonDocument.Parse(replay.Json).RootElement.GetProperty("cartId").GetGuid());Assert.Equal(1,await Scalar(a,"SELECT count(*) FROM orders WHERE product_id=$1"));Assert.Equal(3000,JsonDocument.Parse(result.Json).RootElement.GetProperty("totalCents").GetInt64());var other=await a.NewAccountAsync();Assert.Equal(409,(await service.ReserveAsync(new([new(a.ProductId,2),new(b.ProductId,1)]),key,other)).StatusCode);}
 [Fact] public async Task Cart_RejectsDuplicateProducts()
 {await using var f=await PostgresTestScope.CreateAsync();Assert.Equal(400,(await Cart(f).ReserveAsync(new([new(f.ProductId,1),new(f.ProductId,1)]),f.NewRequestKey(),Guid.NewGuid())).StatusCode);Assert.Equal(400,(await Cart(f).ReserveAsync(new([null!]),f.NewRequestKey(),Guid.NewGuid())).StatusCode);}
 [Fact] public async Task Receipt_IsOwned_AndKeepsSalePrice()
 {await using var f=await PostgresTestScope.CreateAsync();var owner=await f.NewAccountAsync();var r=await Cart(f).ReserveAsync(new([new(f.ProductId,2)]),f.NewRequestKey(),owner);var id=JsonDocument.Parse(r.Json).RootElement.GetProperty("orders")[0].GetProperty("orderId").GetGuid();var repository=new StoreOperationsRepository(f.Db);Assert.Equal("null",await repository.ReceiptAsync(id,Guid.NewGuid()));var receipt=JsonDocument.Parse(await repository.ReceiptAsync(id,owner));Assert.Equal(2000,receipt.RootElement.GetProperty("totalCents").GetInt64());Assert.NotEqual("null",await repository.ReceiptAsync(id,null));}
}
